// Parse tolérant → écrit UNIQUEMENT dans les colonnes RÉELLES du Sheet
// (voir google-apps-script/Code.gs COLUMNS). Toute la richesse (concurrence,
// process, position marché, cible, problèmes, offre) est repliée dans la
// synthèse `audit` ; la douleur chiffrée calcule la `tax`. Aucune colonne
// fantôme.
const form = $('Formulaire — deep-dive').first().json;
const prospect = (form['Prospect (nom exact du CRM)'] || '').toString().trim();
return items.map((it) => {
  const raw = it.json.text || it.json.response || it.json.output || '';
  let x = {};
  try { x = JSON.parse(raw); } catch (e) {
    const m = String(raw).match(/\{[\s\S]*\}/); if (m) { try { x = JSON.parse(m[0]); } catch (_) {} }
  }
  const num = (v) => { const n = parseFloat(String(v).replace(',', '.')); return Number.isFinite(n) ? Math.abs(n) : null; };
  const now = new Date().toISOString().slice(0, 16).replace('T', ' ');
  const mc = num(x.missedCallsPerWeek), at = num(x.avgTicket);
  const tax = (mc && at) ? Math.round(mc * 4.33 * 0.3 * at) : '';
  const auditParts = [
    x.marketPosition ? 'Position: ' + x.marketPosition : '',
    x.audience ? 'Cible: ' + x.audience : '',
    x.localCompetition ? 'Concurrence: ' + x.localCompetition : '',
    x.currentProcess ? 'Process: ' + x.currentProcess : '',
    (mc || at) ? `Douleur: ${mc || '?'} ratés/sem × ${at || '?'} €` : '',
    Array.isArray(x.problems) && x.problems.length ? 'Problèmes: ' + x.problems.join(' | ') : '',
    x.personalizedOffer ? 'Offre pressentie: ' + x.personalizedOffer : '',
    x.summary || ''
  ].filter(Boolean);
  const out = {
    prospect,
    rating: x.rating !== undefined ? num(x.rating) : '',
    reviews: x.reviews !== undefined ? num(x.reviews) : '',
    website: x.websiteState || '',
    audit: auditParts.join(' · ').slice(0, 1500),
    tax: tax,
    history: `[${now}] Deep-dive importé (recherche externe structurée)`
  };
  // ne pas écraser avec du vide : on retire les clés vides/nulles (hors prospect)
  for (const k of Object.keys(out)) { if (k !== 'prospect' && (out[k] === '' || out[k] === null)) delete out[k]; }
  return { json: out };
});
